"""Unit tests for the expanded entity_links extractor + normalizer."""

from __future__ import annotations

import pytest

from family_agent.entity_links import (
    KNOWN_KINDS,
    MAX_ENTITY_LINKS,
    build_entity_link,
    extract_entity_links_from_tool_result,
    normalize_entity_links,
)

pytestmark = pytest.mark.unit


def _ids(links):
    return [(link["kind"], link["id"]) for link in links]


def test_build_entity_link_returns_none_for_unknown_kind():
    assert build_entity_link("widget", "abc", "Widget A") is None


def test_build_entity_link_returns_none_for_missing_fields():
    assert build_entity_link("event", "", "Title") is None
    assert build_entity_link("event", "abc", "") is None
    assert build_entity_link("", "abc", "Title") is None


def test_build_entity_link_produces_url_for_each_known_kind():
    for kind in KNOWN_KINDS:
        link = build_entity_link(kind, "abc-123", "Sample")
        assert link is not None, kind
        assert link["kind"] == kind
        assert link["id"] == "abc-123"
        assert link["label"] == "Sample"
        assert link["url"]


def test_extract_event_results_from_search_calendar_events():
    result = {
        "events": [
            {"event_id": "evt-1", "title": "Soccer"},
            {"event_id": "evt-2", "title": "Dance"},
        ],
    }
    links = extract_entity_links_from_tool_result(
        tool_name="search_calendar_events", tool_result=result
    )
    assert _ids(links) == [("event", "evt-1"), ("event", "evt-2")]


def test_extract_trip_results_uses_id_when_top_level():
    result = [{"id": "trip-1", "name": "Beach Week"}]
    links = extract_entity_links_from_tool_result(
        tool_name="read_trip_summaries", tool_result=result
    )
    assert _ids(links) == [("trip", "trip-1")]


def test_extract_task_list_results_includes_linked_event_and_chore():
    result = {
        "tasks": [
            {
                "id": "task-1",
                "title": "Pack snacks",
                "linked_event": {"id": "evt-9", "title": "Game day"},
                "chore_program": {"id": "chore-1", "title": "Weekly chores"},
            }
        ]
    }
    links = extract_entity_links_from_tool_result(
        tool_name="list_family_tasks", tool_result=result
    )
    assert _ids(links) == [
        ("task", "task-1"),
        ("event", "evt-9"),
        ("chore_program", "chore-1"),
    ]


def test_extract_grocery_list_results_links_trip_alongside():
    result = {
        "lists": [
            {
                "id": "gl-1",
                "name": "Groceries",
                "trip_id": "trip-5",
                "trip_name": "Spring Break",
            }
        ]
    }
    links = extract_entity_links_from_tool_result(
        tool_name="list_grocery_lists", tool_result=result
    )
    assert _ids(links) == [("grocery_list", "gl-1"), ("trip", "trip-5")]


def test_extract_chore_program_results():
    result = {"programs": [{"id": "cp-1", "title": "Take out trash"}]}
    links = extract_entity_links_from_tool_result(
        tool_name="list_chore_programs", tool_result=result
    )
    assert _ids(links) == [("chore_program", "cp-1")]


def test_extract_unknown_tool_returns_empty():
    result = {"event_id": "evt-1", "title": "Soccer"}
    links = extract_entity_links_from_tool_result(
        tool_name="some_unmapped_tool", tool_result=result
    )
    assert links == []


def test_extractor_dedupes_repeats():
    result = {
        "events": [
            {"event_id": "evt-1", "title": "Soccer"},
            {"event_id": "evt-1", "title": "Soccer"},
        ]
    }
    links = extract_entity_links_from_tool_result(
        tool_name="search_calendar_events", tool_result=result
    )
    assert _ids(links) == [("event", "evt-1")]


def test_normalize_entity_links_rejects_unknown_kinds():
    raw = [
        {"kind": "event", "id": "1", "label": "A", "url": "/events/1/"},
        {"kind": "widget", "id": "2", "label": "B", "url": "/widgets/2/"},
    ]
    normalized = normalize_entity_links(raw)
    assert _ids(normalized) == [("event", "1")]


def test_normalize_entity_links_dedupes_and_caps():
    raw = [
        {
            "kind": "event",
            "id": str(i),
            "label": f"Event {i}",
            "url": f"/events/{i}/",
        }
        for i in range(MAX_ENTITY_LINKS + 5)
    ]
    # Add duplicate of first
    raw.append({"kind": "event", "id": "0", "label": "dup", "url": "/x/"})
    normalized = normalize_entity_links(raw)
    assert len(normalized) == MAX_ENTITY_LINKS
    # First entry should still be id=0
    assert normalized[0]["id"] == "0"


def test_normalize_entity_links_rejects_missing_fields():
    raw = [
        {"kind": "event", "id": "1", "label": "A", "url": ""},
        {"kind": "event", "id": "", "label": "A", "url": "/x/"},
        {"kind": "event", "label": "A", "url": "/x/"},
    ]
    assert normalize_entity_links(raw) == []


def test_normalize_entity_links_passes_through_garbage():
    assert normalize_entity_links("not a list") == []
    assert normalize_entity_links([42, "string", None]) == []

"""Unit tests for inline ref marker expansion."""

from __future__ import annotations

import pytest

from family_agent.inline_refs import expand_inline_refs, strip_unresolved_ref_markers

pytestmark = pytest.mark.unit


def _links(*pairs):
    return [
        {
            "kind": kind,
            "id": entity_id,
            "label": label,
            "url": f"/{kind}/{entity_id}/",
        }
        for kind, entity_id, label in pairs
    ]


def test_expand_inline_refs_returns_text_when_no_markers():
    assert expand_inline_refs("Hello world", _links(("event", "1", "X"))) == (
        "Hello world"
    )


def test_expand_inline_refs_replaces_known_marker_with_index():
    text = "Soccer practice [[ref:event:evt-1]] is at 5pm."
    links = _links(("event", "evt-1", "Soccer practice"))
    assert expand_inline_refs(text, links) == "Soccer practice [[ref:0]] is at 5pm."


def test_expand_inline_refs_strips_unknown_marker():
    text = "Soccer [[ref:event:made-up]] is at 5pm."
    links = _links(("event", "evt-1", "Soccer practice"))
    assert expand_inline_refs(text, links) == "Soccer  is at 5pm."


def test_expand_inline_refs_preserves_valid_index_marker():
    text = "See [[ref:0]] next week."
    links = _links(("event", "evt-1", "Soccer practice"))
    assert expand_inline_refs(text, links) == "See [[ref:0]] next week."


def test_expand_inline_refs_strips_out_of_range_index_marker():
    text = "See [[ref:5]] next week."
    links = _links(("event", "evt-1", "Soccer practice"))
    assert expand_inline_refs(text, links) == "See  next week."


def test_expand_inline_refs_handles_multiple_kinds():
    text = (
        "Bring snacks for [[ref:event:evt-1]] and check the "
        "[[ref:grocery_list:gl-2]] beforehand."
    )
    links = _links(
        ("event", "evt-1", "Soccer"),
        ("grocery_list", "gl-2", "Saturday list"),
    )
    assert expand_inline_refs(text, links) == (
        "Bring snacks for [[ref:0]] and check the [[ref:1]] beforehand."
    )


def test_expand_inline_refs_is_case_insensitive_for_kind():
    text = "Trip [[ref:TRIP:t-1]] is locked in."
    links = _links(("trip", "t-1", "Beach"))
    assert expand_inline_refs(text, links) == "Trip [[ref:0]] is locked in."


def test_strip_unresolved_ref_markers_removes_all_marker_shapes():
    text = "Hello [[ref:event:1]] and [[ref:3]] there"
    assert strip_unresolved_ref_markers(text) == "Hello  and  there"


def test_strip_unresolved_ref_markers_is_noop_when_no_marker():
    assert strip_unresolved_ref_markers("plain text") == "plain text"


@pytest.mark.parametrize("text", ["", None])
def test_expand_inline_refs_tolerates_empty(text):
    assert expand_inline_refs(text or "", []) == ""

